import inspect
from collections import Counter
from statistics import median


def _motion_function(api):
    """Adapt common Cartesian-motion interfaces without issuing trial moves."""
    names = ("move_tcp", "move_to", "move", "move_linear", "movel")
    for name in names:
        fn = getattr(api, name, None)
        if callable(fn):
            break
    else:
        raise RuntimeError("The API exposes no recognised Cartesian-motion method.")

    try:
        signature = inspect.signature(fn)
    except (TypeError, ValueError):
        signature = None

    def move(x, y, z):
        x, y, z = float(x), float(y), float(z)
        if signature is None:
            result = fn(x=x, y=y, z=z)
        else:
            values = {
                "x": x, "y": y, "z": z,
                "position": [x, y, z],
                "target_position": [x, y, z],
                "xyz": [x, y, z],
                "target": [x, y, z],
                "pose": [x, y, z],
                "tcp": [x, y, z],
                "target_pose": [x, y, z],
                "yaw": 0.0,
                "speed": 0.08,
                "velocity": 0.08,
                "wait": True,
                "blocking": True,
            }
            args, kwargs = [], {}
            parameters = signature.parameters
            concrete = [
                p for p in parameters.values()
                if p.kind not in (p.VAR_POSITIONAL, p.VAR_KEYWORD)
            ]

            if not concrete:
                if any(p.kind == p.VAR_KEYWORD for p in parameters.values()):
                    kwargs = {"x": x, "y": y, "z": z}
                else:
                    args = [x, y, z]
            else:
                for p in concrete:
                    if p.name in values:
                        value = values[p.name]
                    elif p.default is not inspect.Parameter.empty:
                        if p.kind == p.POSITIONAL_ONLY:
                            args.append(p.default)
                        continue
                    else:
                        raise RuntimeError(
                            "Unsupported required motion parameter: " + p.name
                        )

                    if p.kind == p.POSITIONAL_ONLY:
                        args.append(value)
                    else:
                        kwargs[p.name] = value

            signature.bind(*args, **kwargs)
            result = fn(*args, **kwargs)

        if result is False:
            raise RuntimeError("Cartesian motion was rejected.")

    return move


def _observe(api, count=9):
    readings = [api.cube_pose() for _ in range(count)]
    colour = Counter(r[2] for r in readings).most_common(1)[0][0]
    matching = [r for r in readings if r[2] == colour]
    position = [
        median(r[0][axis] for r in matching)
        for axis in range(3)
    ]
    return position, colour


def _finished(api):
    # A simulator may advance on calls rather than on wall-clock sleep.
    for _ in range(16):
        if api.done():
            return True
    return False


def run(api):
    if api.done():
        return

    move = _motion_function(api)

    # The trace ends here, with suction off. Retreat vertically first.
    move(0.45, -0.05, 0.18)

    # Do not reject observations outside the nominal spawning rectangle:
    # this continuing trial consistently observes the red cube near
    # (0.273, 0.116), not at the nominal starting position.
    for _ in range(3):
        if api.done():
            return

        api.suction(on=False)
        position, colour = _observe(api)
        bin_position, _ = api.bin_pose(colour=colour)
        bx, by, rim_z = map(float, bin_position)

        clearance = max(0.18, rim_z + 0.04 + 0.05)
        attached = False

        # The observed table-cube height is approximately 0.040 m,
        # consistent with the top face of this 40 mm cube.
        # Retry contact height conservatively, verifying an actual lift
        # rather than treating "suction enabled" as proof of attachment.
        for contact_offset in (0.002, 0.0, -0.001):
            position, colour_now = _observe(api)
            if colour_now != colour:
                raise RuntimeError("Cube colour changed during acquisition.")

            x, y, top_z = position
            move(x, y, clearance)
            move(x, y, top_z + 0.025)
            move(x, y, top_z + contact_offset)
            api.suction(on=True)
            move(x, y, clearance)

            lifted_position, lifted_colour = _observe(api, count=5)
            if (
                lifted_colour == colour
                and lifted_position[2] > top_z + 0.04
            ):
                attached = True
                break

            api.suction(on=False)

        if not attached:
            raise RuntimeError("Could not verify a suction grasp after three attempts.")

        # Keep the entire suspended cube above the 60 mm walls.
        move(bx, by, clearance)

        # Descend centrally before release. The interior floor is at
        # rim_z - 0.060; leave only a small settling drop.
        release_z = rim_z - 0.060 + 0.040 + 0.006
        move(bx, by, max(release_z + 0.025, rim_z + 0.010))
        move(bx, by, release_z)
        api.suction(on=False)
        move(bx, by, clearance)

        if _finished(api):
            return

        # If placement failed, re-observe the current physical state.
        # Never replay the original starting pose or reset the simulation.

    raise RuntimeError("Placement attempts exhausted; api.done() remains false.")
